 @Test void actualRetryEndpointResumesScopedHarnessAsrFailureWithoutResettingSavedAudioOrCaptions()throws Exception {
  try(var f=new Fixture();var client=java.net.http.HttpClient.newBuilder().version(java.net.http.HttpClient.Version.HTTP_1_1).build()){
   f.accept(1);assertTrue(f.live.runOnce(f.session.sessionId()));var before=f.events();assertEquals(1,before.size());
   var json=new com.fasterxml.jackson.databind.ObjectMapper();var fault=Map.ofEntries(Map.entry("module","asr"),Map.entry("name","recording-strict-retry-"+id()),Map.entry("enabled",true),Map.entry("priority",10000),Map.entry("method","POST"),Map.entry("path","/inference/asr-nano/modelserving/asr"),Map.entry("match",Map.of("binary_sha256",sha(f.window(2)))),Map.entry("status_code",503),Map.entry("response_type","json"),Map.entry("response_body",Map.of("error","controlled_recording_asr_failure")));
   var created=client.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create("http://127.0.0.1:8792/admin/api/scenarios")).header("Content-Type","application/json").POST(java.net.http.HttpRequest.BodyPublishers.ofByteArray(json.writeValueAsBytes(fault))).build(),java.net.http.HttpResponse.BodyHandlers.ofByteArray());assertEquals(201,created.statusCode());long scenario=json.readTree(created.body()).path("id").asLong();
   try{
    f.accept(2);assertFalse(f.live.runOnce(f.session.sessionId()));assertEquals("DELAYED",f.live.read(f.actor,f.session.sessionId(),"0",64).get("state"));assertEquals(before,f.events());assertEquals(2,f.recordings.ack(f.session.sessionId(),f.session.partId()).highestContiguousSeq());
    var mvc=ama.api.RecordingSubtitleHttpProbe.create(f.live,f.recordings,f.tx,f.access);String path="/api/v1/recordings/"+f.session.sessionId()+"/subtitles/retry",attribute=ama.api.RecordingSubtitleHttpProbe.sessionAttribute();var session=new ResolvedSession(f.actor,"T".repeat(43),java.time.Instant.now().plusSeconds(60));
    var reply=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(path).requestAttr(attribute,session)).andReturn().getResponse();assertEquals(204,reply.getStatus());assertEquals("IDLE",f.live.read(f.actor,f.session.sessionId(),"0",64).get("state"));assertEquals(before,f.events());
    var removed=client.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create("http://127.0.0.1:8792/admin/api/scenarios/"+scenario)).DELETE().build(),java.net.http.HttpResponse.BodyHandlers.discarding());assertEquals(200,removed.statusCode());scenario=0;
    assertTrue(f.live.runOnce(f.session.sessionId()));assertEquals(2,f.events().size());assertEquals(before.getFirst().get("segmentId"),f.events().getLast().get("segmentId"));assertEquals(2,((Number)f.events().getLast().get("revision")).intValue());assertEquals(2,f.recordings.ack(f.session.sessionId(),f.session.partId()).highestContiguousSeq());
   }finally{if(scenario!=0)client.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create("http://127.0.0.1:8792/admin/api/scenarios/"+scenario)).DELETE().build(),java.net.http.HttpResponse.BodyHandlers.discarding());}
  }
 }
 @Test void lateModelResultCannotReviveDeletedMeetingAndDeletionPurgesAllSubtitleContent()throws Exception {
  try(var f=new Fixture();var pool=java.util.concurrent.Executors.newSingleThreadExecutor()){
   f.scenario(1,"不应复活的迟到内容",1000);f.accept(1);java.util.concurrent.Future<Boolean> running=pool.submit(()->f.live.runOnce(f.session.sessionId()));long deadline=System.nanoTime()+java.time.Duration.ofSeconds(10).toNanos();while(j.queryForObject("SELECT COUNT(*) FROM speech_execution e JOIN recording_subtitle_job q ON q.id=e.lease_task_id WHERE q.session_id=?",Integer.class,f.session.sessionId())==0){assertTrue(System.nanoTime()<deadline);Thread.sleep(10);}
   String liveId=j.queryForObject("SELECT id FROM recording_subtitle_job WHERE session_id=?",String.class,f.session.sessionId());f.recordings.finish(f.session.sessionId(),1,Map.of(f.session.partId(),1L));long revision=j.queryForObject("SELECT revision FROM meeting WHERE id=?",Long.class,f.meeting);f.meetings.delete(f.actor,f.meeting,id(),new ama.contract.MeetingContracts.DeleteMeeting(revision),"SUBTITLE_DELETE");assertFalse(running.get(10,java.util.concurrent.TimeUnit.SECONDS));assertThrows(ama.access.MeetingAccess.AccessDeniedException.class,()->f.live.read(f.actor,f.session.sessionId(),"0",64));assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM recording_subtitle_event WHERE meeting_id=?",Integer.class,f.meeting));
   try(var deletion=new JdbcMeetingDeletion(source,f.tx,f.access,f.catalog)){String job=deletion.forMeeting(f.actor,f.meeting).deletionTaskId();for(int n=0;n<180&&!deletion.status(f.actor,job).state().equals("COMPLETE");n++)assertTrue(deletion.runOnce(job));assertEquals("COMPLETE",deletion.status(f.actor,job).state());}
   assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM recording_subtitle_job WHERE meeting_id=?",Integer.class,f.meeting));assertEquals(1,j.queryForObject("SELECT COUNT(*) FROM speech_execution WHERE lane='REALTIME' AND lease_task_id=?",Integer.class,liveId));
  }
 }
